package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var k int
	fmt.Fscan(reader, &k)
	cnt := make([]int, 10)
	for i := 0; i < 4; i++ {
		var s string
		fmt.Fscan(reader, &s)
		for _, c := range s {
			if c >= '1' && c <= '9' {
				cnt[c-'0']++
			}
		}
	}
	for i := 1; i <= 9; i++ {
		if cnt[i] > 2*k {
			fmt.Println("NO")
			return
		}
	}
	fmt.Println("YES")
}
